'use strict';
const { AdapterError, fetchWithTimeout } = require('../adapters/base-adapter');

/**
 * Reference-image → prompt conversion.
 *
 * PixAi's image models are text-to-image only, so when a user attaches a
 * reference image the app asks a vision-capable chat model from the SAME
 * imported workbook (Google Gemini first — its endpoint is OpenAI-compatible —
 * then any VL/vision model, e.g. Kilo's Nemotron VL) to look at the image and
 * write one detailed generation prompt that merges the image with the user's
 * own words. That prompt is then generated by the normal auto model engine.
 */
const VISION_HINT = /gemini|vision|vl\b|gpt-4o|gpt-5|llama-4|qwen[^\s]*vl/i;

function pickVisionTarget(cfg) {
  const chatProviders = (cfg && cfg.chatProviders) || [];
  const flat = [];
  for (const p of chatProviders) {
    for (const m of p.models || []) flat.push({ provider: p, model: m });
  }
  const usable = flat.filter(({ provider, model }) =>
    provider.status === 'active' && model.status === 'active' &&
    (provider.id === 'google-gemini' || VISION_HINT.test(model.vendorModelId || '')));
  if (!usable.length) return null;
  const score = ({ provider, model }) => {
    let s = 0;
    if (provider.id === 'google-gemini') s += 100;
    if (/gemini/i.test(model.vendorModelId)) s += 40;
    if (/flash/i.test(model.vendorModelId)) s += 10;
    if (/vl|vision/i.test(model.vendorModelId)) s += 30;
    if (/:free/i.test(model.vendorModelId)) s += 5;
    return s;
  };
  usable.sort((a, b) => score(b) - score(a));
  return usable[0];
}

const INSTRUCTIONS = {
  describe: 'You write prompts for a text-to-image generator. Look at the reference image and the user request below, then write ONE detailed image-generation prompt (subject, appearance, clothing/objects, setting, background, lighting, style, camera angle) that recreates what the user wants from this image. Reply with ONLY the prompt text — no explanations, no quotes.',
  edit: 'You write prompts for a text-to-image generator. The user wants to EDIT the reference image. Write ONE detailed image-generation prompt describing the FINAL edited image in full (everything that stays the same, plus the user\'s requested change applied). Reply with ONLY the prompt text — no explanations, no quotes.',
};

async function describeReference({ config, getKey, imageDataUrl, userPrompt = '', mode = 'describe', fetchImpl = fetch }) {
  const target = pickVisionTarget(config);
  if (!target) {
    throw new AdapterError('No vision model is available for reference images. Import the latest workbook (it includes Google Gemini) and try again — or generate without a reference image.', { code: 'VISION_UNAVAILABLE' });
  }
  const { provider, model } = target;
  const apiKey = getKey(provider.id);
  if (!apiKey) {
    throw new AdapterError(`No API key saved for ${provider.name}, which is needed to read reference images. Re-import the workbook with its key.`, { code: 'AUTH_FAILED' });
  }
  const base = (provider.baseUrl || '').replace(/\/+$/, '');
  if (!base) throw new AdapterError(`${provider.name} has no Base URL in the workbook.`, { code: 'CONFIG_MISSING' });
  const instruction = (INSTRUCTIONS[mode] || INSTRUCTIONS.describe) + `\n\nUser request: ${String(userPrompt || '').trim() || 'Recreate this image as closely as possible.'}`;
  const res = await fetchWithTimeout(fetchImpl, `${base}/chat/completions`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: model.vendorModelId,
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: instruction },
          { type: 'image_url', image_url: { url: imageDataUrl } },
        ],
      }],
      temperature: 0.4,
      max_tokens: 500,
    }),
  }, 90000);
  const text = await res.text();
  if (!res.ok) {
    let detail = text.slice(0, 200);
    try { const j = JSON.parse(text); detail = (j.error && j.error.message) || detail; } catch { /* keep raw */ }
    throw new AdapterError(`${provider.name} could not read the reference image: ${detail}`, { code: 'VISION_FAILED', diagnostic: `HTTP ${res.status}: ${detail}` });
  }
  let j;
  try { j = JSON.parse(text); } catch { throw new AdapterError('The vision model returned an unreadable response.', { code: 'BAD_RESPONSE' }); }
  const msg = j.choices && j.choices[0] && j.choices[0].message;
  let content = msg && msg.content;
  if (Array.isArray(content)) content = content.map((c) => (typeof c === 'string' ? c : (c.text || ''))).join(' ');
  const prompt = String(content || '').trim().replace(/^["']|["']$/g, '');
  if (!prompt) throw new AdapterError('The vision model returned an empty prompt.', { code: 'BAD_RESPONSE' });
  return { prompt, visionModelName: model.name, visionProviderName: provider.name };
}

module.exports = { pickVisionTarget, describeReference, VISION_HINT };
